   139→func TestExplainCommit_WithEntireData(t *testing.T) {
   140→	tmpDir := t.TempDir()
   141→	t.Chdir(tmpDir)
   142→
   143→	// Initialize git repo
   144→	repo, err := git.PlainInit(tmpDir, false)
   145→	if err != nil {
   146→		t.Fatalf("failed to init git repo: %v", err)
   147→	}
   148→
   149→	w, err := repo.Worktree()
   150→	if err != nil {
   151→		t.Fatalf("failed to get worktree: %v", err)
   152→	}
   153→
   154→	// Create session metadata directory first
   155→	sessionID := "2025-12-09-test-session-xyz789"
   156→	sessionDir := filepath.Join(tmpDir, ".entire", "metadata", sessionID)
   157→	if err := os.MkdirAll(sessionDir, 0o750); err != nil {
   158→		t.Fatalf("failed to create session dir: %v", err)
   159→	}
   160→
   161→	// Create prompt file
   162→	promptContent := "Add new feature"
   163→	if err := os.WriteFile(filepath.Join(sessionDir, paths.PromptFileName), []byte(promptContent), 0o644); err != nil {
   164→		t.Fatalf("failed to create prompt file: %v", err)
   165→	}
   166→
   167→	// Create a commit with Entire metadata trailer
   168→	testFile := filepath.Join(tmpDir, "test.txt")
   169→	if err := os.WriteFile(testFile, []byte("feature content"), 0o644); err != nil {
   170→		t.Fatalf("failed to write test file: %v", err)
   171→	}
   172→	if _, err := w.Add("test.txt"); err != nil {
   173→		t.Fatalf("failed to add test file: %v", err)
   174→	}
   175→
   176→	// Commit with Entire-Metadata trailer
   177→	metadataDir := ".entire/metadata/" + sessionID
   178→	commitMessage := trailers.FormatMetadata("Add new feature", metadataDir)
   179→	commitHash, err := w.Commit(commitMessage, &git.CommitOptions{
   180→		Author: &object.Signature{
   181→			Name:  "Test",
   182→			Email: "test@example.com",
   183→		},
   184→	})
   185→	if err != nil {
   186→		t.Fatalf("failed to create commit: %v", err)
   187→	}
   188→
   189→	var stdout bytes.Buffer
   190→	err = runExplainCommit(&stdout, commitHash.String())
   191→	if err != nil {
   192→		t.Fatalf("runExplainCommit() error = %v", err)
   193→	}
   194→
   195→	output := stdout.String()
   196→
   197→	// Should show commit info
   198→	if !strings.Contains(output, commitHash.String()[:7]) {
   199→		t.Errorf("expected output to contain short commit hash, got: %s", output)
   200→	}
   201→	// Should show session info - the session ID is extracted from the metadata path
   202→	// The format is test-session-xyz789 (extracted from the full path)
   203→	if !strings.Contains(output, "Session:") {
   204→		t.Errorf("expected output to contain 'Session:', got: %s", output)
   205→	}
   206→}
