   237→		t.Fatalf("failed to create initial commit: %v", err)
   238→	}
   239→
   240→	// Create .entire directory
   241→	if err := os.MkdirAll(".entire", 0o750); err != nil {
   242→		t.Fatalf("failed to create .entire dir: %v", err)
