func TestExplain_CheckpointFlag(t *testing.T) {
	env := NewTestEnv(t)
	defer env.Cleanup()

	// Setup with auto-commit strategy
	env.InitRepo()
	env.WriteFile("README.md", "# Test")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
	env.GitCheckoutNewBranch("feature/test")
	env.InitEntire(strategy.StrategyNameAutoCommit)

	// Create session and checkpoint
	session := env.NewSession()
	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}

	env.WriteFile("main.go", "package main\n\nfunc main() {}\n")
	session.CreateTranscript("Create main", []FileChange{{Path: "main.go", Content: "package main"}})

	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop failed: %v", err)
	}

	// Get checkpoint ID
	checkpointID := env.GetLastCheckpointID()
	if checkpointID == "" {
		t.Fatal("No checkpoint ID found")
	}

	// Test --checkpoint with prefix
	output := env.RunCLI("explain", "--checkpoint", checkpointID[:6], "--no-pager")

	if !strings.Contains(output, "Checkpoint:") {
		t.Errorf("expected 'Checkpoint:' in output, got:\n%s", output)
	}
	if !strings.Contains(output, "Session:") {
		t.Errorf("expected 'Session:' in output, got:\n%s", output)
	}
	if !strings.Contains(output, "Intent:") {
		t.Errorf("expected 'Intent:' in output, got:\n%s", output)
	}
}

