  entire explain --checkpoint abc         Explain checkpoint by ID prefix
  entire explain --checkpoint abc -v      With prompts and files
  entire explain --checkpoint abc --full  With full transcript
  entire explain --session <id>           Explain specific session
  entire explain --commit <sha>           Explain specific commit`,
