// hasCodeChanges checks if a commit has changes outside .entire/ (i.e., actual code changes).
// Returns true if there are code changes, false if only metadata in .entire/ changed.
func hasCodeChanges(commit *object.Commit) bool {
	if commit.NumParents() == 0 {
		return true // First commit, assume meaningful
	}

	parent, err := commit.Parent(0)
	if err != nil {
		return true
	}

	commitTree, err := commit.Tree()
	if err != nil {
		return true
	}

	parentTree, err := parent.Tree()
	if err != nil {
		return true
	}

	changes, err := parentTree.Diff(commitTree)
	if err != nil {
		return true
	}

	for _, change := range changes {
		name := change.To.Name
		if name == "" {
			name = change.From.Name
		}
		if !strings.HasPrefix(name, ".entire/") {
			return true
		}
	}

	return false
}

