   543→func TestFormatSessionInfo_CheckpointNumberingReversed(t *testing.T) {
   544→	now := time.Now()
   545→	session := &strategy.Session{
   546→		ID:          "2025-12-09-test-session",
   547→		Strategy:    "auto-commit",
