   550→	}
   551→
   552→	// Simulate checkpoints coming in newest-first order from ListSessions
   553→	// but numbered with oldest=1, newest=N
   554→	checkpointDetails := []checkpointDetail{
   555→		{
   556→			Index:     3, // Newest checkpoint should have highest number
   557→			ShortID:   "ccc3333",
   558→			Timestamp: now,
   559→			Message:   "Third (newest) checkpoint",
   560→			Interactions: []interaction{{
   561→				Prompt:    "Latest change",
   562→				Responses: []string{},
   563→			}},
   564→		},
   565→		{
   566→			Index:     2,
   567→			ShortID:   "bbb2222",
   568→			Timestamp: now.Add(-time.Hour),
   569→			Message:   "Second checkpoint",
   570→			Interactions: []interaction{{
   571→				Prompt:    "Middle change",
   572→				Responses: []string{},
   573→			}},
   574→		},
   575→		{
   576→			Index:     1, // Oldest checkpoint should be #1
   577→			ShortID:   "aaa1111",
   578→			Timestamp: now.Add(-2 * time.Hour),
   579→			Message:   "First (oldest) checkpoint",
   580→			Interactions: []interaction{{
   581→				Prompt:    "Initial change",
   582→				Responses: []string{},
   583→			}},
   584→		},
   585→	}
   586→
   587→	output := formatSessionInfo(session, "", checkpointDetails)
   588→
   589→	// Verify checkpoint ordering in output
   590→	// Checkpoint 3 should appear before Checkpoint 2 which should appear before Checkpoint 1
   591→	idx3 := strings.Index(output, "Checkpoint 3")
   592→	idx2 := strings.Index(output, "Checkpoint 2")
   593→	idx1 := strings.Index(output, "Checkpoint 1")
   594→
   595→	if idx3 == -1 || idx2 == -1 || idx1 == -1 {
   596→		t.Fatalf("expected all checkpoints to be in output, got:\n%s", output)
