package checkpoint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/logging"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

const (
	// ShadowBranchPrefix is the prefix for shadow branches.
	ShadowBranchPrefix = "entire/"

	// ShadowBranchHashLength is the number of hex characters used in shadow branch names.
	// Shadow branches are named "entire/<hash>" using the first 7 characters of the commit hash.
	ShadowBranchHashLength = 7

	// gitDir and entireDir are excluded from tree operations.
	gitDir    = ".git"
	entireDir = ".entire"
)

// WriteTemporary writes a temporary checkpoint to a shadow branch.
// Shadow branches are named entire/<base-commit-short-hash>.
// Returns the result containing commit hash and whether it was skipped.
// If the new tree hash matches the last checkpoint's tree hash, the checkpoint
// is skipped to avoid duplicate commits (deduplication).
func (s *GitStore) WriteTemporary(ctx context.Context, opts WriteTemporaryOptions) (WriteTemporaryResult, error) {
	_ = ctx // Reserved for future use (e.g., cancellation)

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return WriteTemporaryResult{}, errors.New("BaseCommit is required for temporary checkpoint")
	}

	// Validate session ID to prevent path traversal
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("invalid temporary checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Get the last checkpoint's tree hash for deduplication
	var lastTreeHash plumbing.Hash
	if parentHash != plumbing.ZeroHash {
		if lastCommit, err := s.repo.CommitObject(parentHash); err == nil {
			lastTreeHash = lastCommit.TreeHash
		}
	}

	// Collect all files to include
	var allFiles []string
	if opts.IsFirstCheckpoint {
		// For the first checkpoint of this session, capture ALL files in working directory
		// This ensures untracked files present at session start are included
		allFiles, err = collectWorkingDirectoryFiles()
		if err != nil {
			return WriteTemporaryResult{}, fmt.Errorf("failed to collect working directory files: %w", err)
		}
	} else {
		// For subsequent checkpoints, only include modified/new files
		allFiles = make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
		allFiles = append(allFiles, opts.ModifiedFiles...)
		allFiles = append(allFiles, opts.NewFiles...)
	}

	// Build tree with changes
	treeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, opts.MetadataDir, opts.MetadataDirAbs)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to build tree: %w", err)
	}

	// Deduplication: skip if tree hash matches the last checkpoint
	if lastTreeHash != plumbing.ZeroHash && treeHash == lastTreeHash {
		return WriteTemporaryResult{
			CommitHash: parentHash,
			Skipped:    true,
		}, nil
	}

	// Create checkpoint commit with trailers
	commitMsg := trailers.FormatShadowCommit(opts.CommitMessage, opts.MetadataDir, opts.SessionID)

	commitHash, err := s.createCommit(treeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to update branch reference: %w", err)
	}

	return WriteTemporaryResult{
		CommitHash: commitHash,
		Skipped:    false,
	}, nil
}

// ReadTemporary reads the latest checkpoint from a shadow branch.
// Returns nil if the shadow branch doesn't exist.
func (s *GitStore) ReadTemporary(ctx context.Context, baseCommit string) (*ReadTemporaryResult, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Branch not found is an expected case
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	// Extract session ID and metadata dir from commit trailers
	sessionID, _ := trailers.ParseSession(commit.Message)
	metadataDir, _ := trailers.ParseMetadata(commit.Message)

	return &ReadTemporaryResult{
		CommitHash:  ref.Hash(),
		TreeHash:    commit.TreeHash,
		SessionID:   sessionID,
		MetadataDir: metadataDir,
		Timestamp:   commit.Author.When,
	}, nil
}

// ListTemporary lists all shadow branches with their checkpoint info.
func (s *GitStore) ListTemporary(ctx context.Context) ([]TemporaryInfo, error) {
	_ = ctx // Reserved for future use

	iter, err := s.repo.Branches()
	if err != nil {
		return nil, fmt.Errorf("failed to list branches: %w", err)
	}

	var results []TemporaryInfo
	err = iter.ForEach(func(ref *plumbing.Reference) error {
		branchName := ref.Name().Short()
		if !strings.HasPrefix(branchName, ShadowBranchPrefix) {
			return nil
		}

		// Skip the sessions branch
		if branchName == paths.MetadataBranchName {
			return nil
		}

		commit, commitErr := s.repo.CommitObject(ref.Hash())
		if commitErr != nil {
			//nolint:nilerr // Skip branches we can't read (non-fatal)
			return nil
		}

		sessionID, _ := trailers.ParseSession(commit.Message)

		// Extract base commit from branch name
		baseCommit := strings.TrimPrefix(branchName, ShadowBranchPrefix)

		results = append(results, TemporaryInfo{
			BranchName:   branchName,
			BaseCommit:   baseCommit,
			LatestCommit: ref.Hash(),
			SessionID:    sessionID,
			Timestamp:    commit.Author.When,
		})

		return nil
	})

	if err != nil {
		return nil, fmt.Errorf("failed to iterate branches: %w", err)
	}

	return results, nil
}

// WriteTemporaryTask writes a task checkpoint to a shadow branch.
// Task checkpoints include both code changes and task-specific metadata.
// Returns the commit hash of the created checkpoint.
func (s *GitStore) WriteTemporaryTask(ctx context.Context, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	_ = ctx // Reserved for future use

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return plumbing.ZeroHash, errors.New("BaseCommit is required for task checkpoint")
	}

	// Validate identifiers to prevent path traversal and malformed data
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateToolUseID(opts.ToolUseID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateAgentID(opts.AgentID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Collect all files to include in the commit
	allFiles := make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
	allFiles = append(allFiles, opts.ModifiedFiles...)
	allFiles = append(allFiles, opts.NewFiles...)

	// Build new tree with code changes (no metadata dir yet)
	newTreeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, "", "")
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to build tree: %w", err)
	}

	// Add task metadata to tree
	newTreeHash, err = s.addTaskMetadataToTree(newTreeHash, opts)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to add task metadata: %w", err)
	}

	// Create the commit
	commitHash, err := s.createCommit(newTreeHash, parentHash, opts.CommitMessage, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update shadow branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(ref); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to update shadow branch reference: %w", err)
	}

	return commitHash, nil
}

// addTaskMetadataToTree adds task checkpoint metadata to a git tree.
// When IsIncremental is true, only adds the incremental checkpoint file.
func (s *GitStore) addTaskMetadataToTree(baseTreeHash plumbing.Hash, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	// Get base tree and flatten it
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten tree: %w", err)
	}

	// Compute metadata paths
	sessionMetadataDir := paths.EntireMetadataDir + "/" + opts.SessionID
	taskMetadataDir := sessionMetadataDir + "/tasks/" + opts.ToolUseID

	if opts.IsIncremental {
		// Incremental checkpoint: only add the checkpoint file
		// Use proper JSON marshaling to handle nil/empty IncrementalData correctly
		incrementalCheckpoint := struct {
			Type      string          `json:"type"`
			ToolUseID string          `json:"tool_use_id"`
			Timestamp time.Time       `json:"timestamp"`
			Data      json.RawMessage `json:"data"`
		}{
			Type:      opts.IncrementalType,
			ToolUseID: opts.ToolUseID,
			Timestamp: time.Now().UTC(),
			Data:      opts.IncrementalData,
		}
		cpData, err := jsonutil.MarshalIndentWithNewline(incrementalCheckpoint, "", "  ")
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
		}

		cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
		}
		cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
		cpPath := taskMetadataDir + "/checkpoints/" + cpFilename
		entries[cpPath] = object.TreeEntry{
			Name: cpPath,
			Mode: filemode.Regular,
			Hash: cpBlobHash,
		}
	} else {
		// Final checkpoint: add transcripts and checkpoint.json

		// Add session transcript (with chunking support for large transcripts)
		if opts.TranscriptPath != "" {
			if transcriptContent, readErr := os.ReadFile(opts.TranscriptPath); readErr == nil {
				// Detect agent type from content for proper chunking
				agentType := agent.DetectAgentTypeFromContent(transcriptContent)

				// Chunk if necessary
				chunks, chunkErr := agent.ChunkTranscript(transcriptContent, agentType)
				if chunkErr != nil {
					logging.Warn(context.Background(), "failed to chunk transcript, checkpoint will be saved without transcript",
						slog.String("error", chunkErr.Error()),
						slog.String("session_id", opts.SessionID),
					)
				} else {
					for i, chunk := range chunks {
						chunkPath := sessionMetadataDir + "/" + agent.ChunkFileName(paths.TranscriptFileName, i)
						blobHash, blobErr := CreateBlobFromContent(s.repo, chunk)
						if blobErr != nil {
							logging.Warn(context.Background(), "failed to create blob for transcript chunk",
								slog.String("error", blobErr.Error()),
								slog.String("session_id", opts.SessionID),
								slog.Int("chunk_index", i),
							)
							continue
						}
						entries[chunkPath] = object.TreeEntry{
							Name: chunkPath,
							Mode: filemode.Regular,
							Hash: blobHash,
						}
					}
				}
			}
		}

		// Add subagent transcript if available
		if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
			if agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath); readErr == nil {
				if blobHash, blobErr := CreateBlobFromContent(s.repo, agentContent); blobErr == nil {
					agentPath := taskMetadataDir + "/agent-" + opts.AgentID + ".jsonl"
					entries[agentPath] = object.TreeEntry{
						Name: agentPath,
						Mode: filemode.Regular,
						Hash: blobHash,
					}
				}
			}
		}

		// Add checkpoint.json
		checkpointJSON := fmt.Sprintf(`{
  "session_id": %q,
  "tool_use_id": %q,
  "checkpoint_uuid": %q,
  "agent_id": %q
}`, opts.SessionID, opts.ToolUseID, opts.CheckpointUUID, opts.AgentID)

		blobHash, err := CreateBlobFromContent(s.repo, []byte(checkpointJSON))
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create checkpoint blob: %w", err)
		}
		checkpointPath := taskMetadataDir + "/checkpoint.json"
		entries[checkpointPath] = object.TreeEntry{
			Name: checkpointPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Build new tree from entries
	return BuildTreeFromEntries(s.repo, entries)
}

// ListTemporaryCheckpoints lists all checkpoint commits on a shadow branch.
// This returns individual commits (rewind points), not just branch info.
// The sessionID filter, if provided, limits results to commits from that session.
func (s *GitStore) ListTemporaryCheckpoints(ctx context.Context, baseCommit string, sessionID string, limit int) ([]TemporaryCheckpointInfo, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilerr // No shadow branch is expected case
	}

	iter, err := s.repo.Log(&git.LogOptions{From: ref.Hash()})
	if err != nil {
		return nil, fmt.Errorf("failed to get commit log: %w", err)
	}

	var results []TemporaryCheckpointInfo
	count := 0

	err = iter.ForEach(func(c *object.Commit) error {
		if count >= limit*5 { // Scan more to allow for session filtering
			return errStop
		}
		count++

		// Verify commit belongs to target session via Entire-Session trailer
		commitSessionID, hasTrailer := trailers.ParseSession(c.Message)
		if !hasTrailer {
			return nil // Skip commits without session trailer
		}
		if sessionID != "" && commitSessionID != sessionID {
			return nil // Skip commits from other sessions
		}

		// Get first line of message
		message := c.Message
		if idx := strings.Index(message, "\n"); idx > 0 {
			message = message[:idx]
		}

		info := TemporaryCheckpointInfo{
			CommitHash: c.Hash,
			Message:    message,
			SessionID:  commitSessionID,
			Timestamp:  c.Author.When,
		}

		// Check for task checkpoint first
		taskMetadataDir, foundTask := trailers.ParseTaskMetadata(c.Message)
		if foundTask {
			info.IsTaskCheckpoint = true
			info.MetadataDir = taskMetadataDir
			info.ToolUseID = extractToolUseIDFromPath(taskMetadataDir)
		} else {
			metadataDir, found := trailers.ParseMetadata(c.Message)
			if found {
				info.MetadataDir = metadataDir
			}
		}

		results = append(results, info)

		if len(results) >= limit {
			return errStop
		}
		return nil
	})

	if err != nil && !errors.Is(err, errStop) {
		return nil, fmt.Errorf("error iterating commits: %w", err)
	}

	return results, nil
}

// extractToolUseIDFromPath extracts the ToolUseID from a task metadata directory path.
// Task metadata dirs have format: .entire/metadata/<session>/tasks/<toolUseID>
func extractToolUseIDFromPath(metadataDir string) string {
	parts := strings.Split(metadataDir, "/")
	if len(parts) >= 2 && parts[len(parts)-2] == "tasks" {
		return parts[len(parts)-1]
	}
	return ""
}

// errStop is a sentinel error used to break out of git log iteration.
var errStop = errors.New("stop iteration")

// GetTranscriptFromCommit retrieves the transcript from a specific commit's tree.
// This is used for shadow branch checkpoints where the transcript is stored in the commit tree
// rather than on the entire/sessions branch.
// commitHash is the commit to read from, metadataDir is the path within the tree.
// agentType is used for reassembling chunked transcripts in the correct format.
// Handles both chunked and non-chunked transcripts.
func (s *GitStore) GetTranscriptFromCommit(commitHash plumbing.Hash, metadataDir string, agentType agent.AgentType) ([]byte, error) {
	commit, err := s.repo.CommitObject(commitHash)
	if err != nil {
		return nil, fmt.Errorf("failed to get commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get commit tree: %w", err)
	}

	// Try to get the metadata subtree for chunk detection
	subTree, subTreeErr := tree.Tree(metadataDir)
	if subTreeErr == nil {
		// Use the helper function that handles chunking
		transcript, err := readTranscriptFromTree(subTree, agentType)
		if err == nil && transcript != nil {
			return transcript, nil
		}
	}

	// Fall back to direct file access (for backwards compatibility)
	transcriptPath := metadataDir + "/" + paths.TranscriptFileName
	if file, fileErr := tree.File(transcriptPath); fileErr == nil {
		content, contentErr := file.Contents()
		if contentErr == nil {
			return []byte(content), nil
		}
	}

	transcriptPath = metadataDir + "/" + paths.TranscriptFileNameLegacy
	if file, fileErr := tree.File(transcriptPath); fileErr == nil {
		content, contentErr := file.Contents()
		if contentErr == nil {
			return []byte(content), nil
		}
	}

	return nil, ErrNoTranscript
}

// ShadowBranchExists checks if a shadow branch exists for the given base commit.
func (s *GitStore) ShadowBranchExists(baseCommit string) bool {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	_, err := s.repo.Reference(refName, true)
	return err == nil
}

// DeleteShadowBranch deletes the shadow branch for the given base commit.
func (s *GitStore) DeleteShadowBranch(baseCommit string) error {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	if err := s.repo.Storer.RemoveReference(refName); err != nil {
		return fmt.Errorf("failed to delete shadow branch %s: %w", shadowBranchName, err)
	}
	return nil
}

// ShadowBranchNameForCommit returns the shadow branch name for a base commit hash.
// Uses the first ShadowBranchHashLength characters of the commit hash.
func ShadowBranchNameForCommit(baseCommit string) string {
	if len(baseCommit) >= ShadowBranchHashLength {
		return ShadowBranchPrefix + baseCommit[:ShadowBranchHashLength]
	}
	return ShadowBranchPrefix + baseCommit
}

// getOrCreateShadowBranch gets or creates the shadow branch for checkpoints.
// Returns (parentHash, baseTreeHash, error).
func (s *GitStore) getOrCreateShadowBranch(branchName string) (plumbing.Hash, plumbing.Hash, error) {
	refName := plumbing.NewBranchReferenceName(branchName)
	ref, err := s.repo.Reference(refName, true)

	if err == nil {
		// Branch exists
		commit, err := s.repo.CommitObject(ref.Hash())
		if err != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
		}
		return ref.Hash(), commit.TreeHash, nil
	}

	// Branch doesn't exist, use current HEAD's tree as base
	head, err := s.repo.Head()
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD: %w", err)
	}

	headCommit, err := s.repo.CommitObject(head.Hash())
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD commit: %w", err)
	}

	return plumbing.ZeroHash, headCommit.TreeHash, nil
}

// buildTreeWithChanges builds a git tree with the given changes.
// metadataDir is the relative path for git tree entries, metadataDirAbs is the absolute path
// for filesystem operations (needed when CLI is run from a subdirectory).
func (s *GitStore) buildTreeWithChanges(
	baseTreeHash plumbing.Hash,
	modifiedFiles, deletedFiles []string,
	metadataDir, metadataDirAbs string,
) (plumbing.Hash, error) {
	// Get repo root for resolving file paths
	// This is critical because fileExists() and createBlobFromFile() use os.Stat()
	// which resolves relative to CWD. The modifiedFiles are repo-relative paths,
	// so we must resolve them against repo root, not CWD.
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get repo root: %w", err)
	}

	// Get the base tree
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	// Flatten existing tree
	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten base tree: %w", err)
	}

	// Remove deleted files
	for _, file := range deletedFiles {
		delete(entries, file)
	}

	// Add/update modified files
	for _, file := range modifiedFiles {
		// Resolve path relative to repo root for filesystem operations
		absPath := filepath.Join(repoRoot, file)
		if !fileExists(absPath) {
			delete(entries, file)
			continue
		}

		blobHash, mode, err := createBlobFromFile(s.repo, absPath)
		if err != nil {
			// Skip files that can't be staged (may have been deleted since detection)
			continue
		}

		entries[file] = object.TreeEntry{
			Name: file,
			Mode: mode,
			Hash: blobHash,
		}
	}

	// Add metadata directory files
	if metadataDir != "" && metadataDirAbs != "" {
		if err := addDirectoryToEntriesWithAbsPath(s.repo, metadataDirAbs, metadataDir, entries); err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to add metadata directory: %w", err)
		}
	}

	// Build tree
	return BuildTreeFromEntries(s.repo, entries)
}

// createCommit creates a commit object.
func (s *GitStore) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:  treeHash,
		Author:    sig,
		Committer: sig,
		Message:   message,
	}

	// Add parent if not a new branch
	if parentHash != plumbing.ZeroHash {
		commit.ParentHashes = []plumbing.Hash{parentHash}
	}

	obj := s.repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := s.repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

// Helper functions extracted from strategy/common.go
// These are exported for use by strategy package (push_common.go, session_test.go)

// FlattenTree recursively flattens a tree into a map of full paths to entries.
func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
	for _, entry := range tree.Entries {
		fullPath := entry.Name
		if prefix != "" {
			fullPath = prefix + "/" + entry.Name
		}

		if entry.Mode == filemode.Dir {
			// Recurse into subtree
			subtree, err := repo.TreeObject(entry.Hash)
			if err != nil {
				return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
			}
			if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
				return err
			}
		} else {
			entries[fullPath] = object.TreeEntry{
				Name: fullPath,
				Mode: entry.Mode,
				Hash: entry.Hash,
			}
		}
	}
	return nil
}

// fileExists checks if a file exists at the given path.
func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// createBlobFromFile creates a blob object from a file in the working directory.
func createBlobFromFile(repo *git.Repository, filePath string) (plumbing.Hash, filemode.FileMode, error) {
	info, err := os.Stat(filePath)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
	}

	// Determine file mode
	mode := filemode.Regular
	if info.Mode()&0o111 != 0 {
		mode = filemode.Executable
	}
	if info.Mode()&os.ModeSymlink != 0 {
		mode = filemode.Symlink
	}

	// Read file contents
	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the repository
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
	}

	// Create blob object
	obj := repo.Storer.NewEncodedObject()
	obj.SetType(plumbing.BlobObject)
	obj.SetSize(int64(len(content)))

	writer, err := obj.Writer()
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to get object writer: %w", err)
	}

	_, err = writer.Write(content)
	if err != nil {
		_ = writer.Close()
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to write blob content: %w", err)
	}
	if err := writer.Close(); err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to close blob writer: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to store blob object: %w", err)
	}

	return hash, mode, nil
}

// addDirectoryToEntriesWithAbsPath recursively adds all files in a directory to the entries map.
func addDirectoryToEntriesWithAbsPath(repo *git.Repository, dirPathAbs, dirPathRel string, entries map[string]object.TreeEntry) error {
	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}

		// Calculate relative path within the directory, then join with dirPathRel for tree entry
		relWithinDir, err := filepath.Rel(dirPathAbs, path)
		if err != nil {
			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
		}

		blobHash, mode, err := createBlobFromFile(repo, path)
		if err != nil {
			return fmt.Errorf("failed to create blob for %s: %w", path, err)
		}

		treePath := filepath.Join(dirPathRel, relWithinDir)
		entries[treePath] = object.TreeEntry{
			Name: treePath,
			Mode: mode,
			Hash: blobHash,
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
	}
	return nil
}

// treeNode represents a node in our tree structure.
type treeNode struct {
	entries map[string]*treeNode // subdirectories
	files   []object.TreeEntry   // files in this directory
}

// BuildTreeFromEntries builds a proper git tree structure from flattened file entries.
// Exported for use by strategy package (push_common.go, session_test.go)
func BuildTreeFromEntries(repo *git.Repository, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
	// Build a tree structure
	root := &treeNode{
		entries: make(map[string]*treeNode),
		files:   []object.TreeEntry{},
	}

	// Insert all entries into the tree structure
	for fullPath, entry := range entries {
		parts := strings.Split(fullPath, "/")
		insertIntoTree(root, parts, entry)
	}

	// Recursively build tree objects from bottom up
	return buildTreeObject(repo, root)
}

// insertIntoTree inserts a file entry into the tree structure.
func insertIntoTree(node *treeNode, pathParts []string, entry object.TreeEntry) {
	if len(pathParts) == 1 {
		// This is a file in the current directory
		node.files = append(node.files, object.TreeEntry{
			Name: pathParts[0],
			Mode: entry.Mode,
			Hash: entry.Hash,
		})
		return
	}

	// This is in a subdirectory
	dirName := pathParts[0]
	if node.entries[dirName] == nil {
		node.entries[dirName] = &treeNode{
			entries: make(map[string]*treeNode),
			files:   []object.TreeEntry{},
		}
	}
	insertIntoTree(node.entries[dirName], pathParts[1:], entry)
}

// buildTreeObject recursively builds tree objects from a treeNode.
func buildTreeObject(repo *git.Repository, node *treeNode) (plumbing.Hash, error) {
	var treeEntries []object.TreeEntry

	// Add files
	treeEntries = append(treeEntries, node.files...)

	// Recursively build subtrees
	for name, subnode := range node.entries {
		subHash, err := buildTreeObject(repo, subnode)
		if err != nil {
			return plumbing.ZeroHash, err
		}
		treeEntries = append(treeEntries, object.TreeEntry{
			Name: name,
			Mode: filemode.Dir,
			Hash: subHash,
		})
	}

	// Sort entries (git requires sorted entries)
	sortTreeEntries(treeEntries)

	// Create tree object
	tree := &object.Tree{Entries: treeEntries}

	obj := repo.Storer.NewEncodedObject()
	if err := tree.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
	}

	return hash, nil
}

// sortTreeEntries sorts tree entries in git's required order.
// Git sorts tree entries by name, with directories having a trailing /
func sortTreeEntries(entries []object.TreeEntry) {
	sort.Slice(entries, func(i, j int) bool {
		nameI := entries[i].Name
		nameJ := entries[j].Name
		if entries[i].Mode == filemode.Dir {
			nameI += "/"
		}
		if entries[j].Mode == filemode.Dir {
			nameJ += "/"
		}
		return nameI < nameJ
	})
}

// collectWorkingDirectoryFiles collects all files in the working directory.
// Excludes .git/ and .entire/ directories.
func collectWorkingDirectoryFiles() ([]string, error) {
	// Get repository root to walk from there
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		repoRoot = "." // Fallback to current directory
	}

	var files []string
	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil //nolint:nilerr // Skip filesystem errors during walk
		}

		// Get path relative to repo root
		relPath, err := filepath.Rel(repoRoot, path)
		if err != nil {
			return nil //nolint:nilerr // Skip paths we can't make relative
		}

		// Skip directories
		if info.IsDir() {
			// Skip .git and .entire directories
			if relPath == gitDir || relPath == entireDir ||
				strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
				return filepath.SkipDir
			}
			return nil
		}

		// Skip files in special directories (shouldn't reach here due to SkipDir, but safety check)
		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
			return nil
		}

		files = append(files, relPath)
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to walk directory: %w", err)
	}

	return files, nil
}

// Package trailers provides parsing and formatting for Entire commit message trailers.
// Trailers are key-value metadata appended to git commit messages following the
// git trailer convention (key: value format after a blank line).
package trailers

import (
	"fmt"
	"regexp"
	"strings"

	checkpointID "entire.io/cli/cmd/entire/cli/checkpoint/id"
)

// Trailer key constants used in commit messages.
const (
	// MetadataTrailerKey points to the metadata directory within a commit tree.
	MetadataTrailerKey = "Entire-Metadata"

	// MetadataTaskTrailerKey points to the task metadata directory for subagent checkpoints.
	MetadataTaskTrailerKey = "Entire-Metadata-Task"

	// StrategyTrailerKey indicates which strategy created the commit.
	StrategyTrailerKey = "Entire-Strategy"

	// BaseCommitTrailerKey links shadow commits to their base code commit.
	BaseCommitTrailerKey = "Base-Commit"

	// SessionTrailerKey identifies which session created a commit.
	SessionTrailerKey = "Entire-Session"

	// CondensationTrailerKey identifies the condensation ID for a commit (legacy).
	CondensationTrailerKey = "Entire-Condensation"

	// SourceRefTrailerKey links code commits to their metadata on a shadow/metadata branch.
	// Format: "<branch>@<commit-hash>" e.g. "entire/metadata@abc123def456"
	SourceRefTrailerKey = "Entire-Source-Ref"

	// CheckpointTrailerKey links commits to their checkpoint metadata on entire/sessions.
	// Format: 12 hex characters e.g. "a3b2c4d5e6f7"
	// This trailer survives git amend and rebase operations.
	CheckpointTrailerKey = "Entire-Checkpoint"

	// EphemeralBranchTrailerKey identifies the shadow branch that a checkpoint originated from.
	// Used in manual-commit strategy checkpoint commits on entire/sessions branch.
	// Format: full branch name e.g. "entire/2b4c177"
	EphemeralBranchTrailerKey = "Ephemeral-branch"

	// AgentTrailerKey identifies the agent that created a checkpoint.
	// Format: human-readable agent name e.g. "Claude Code", "Cursor"
	AgentTrailerKey = "Entire-Agent"
)

// Pre-compiled regexes for trailer parsing.
var (
	// Trailer parsing regexes.
	strategyTrailerRegex     = regexp.MustCompile(StrategyTrailerKey + `:\s*(.+)`)
	metadataTrailerRegex     = regexp.MustCompile(MetadataTrailerKey + `:\s*(.+)`)
	taskMetadataTrailerRegex = regexp.MustCompile(MetadataTaskTrailerKey + `:\s*(.+)`)
	baseCommitTrailerRegex   = regexp.MustCompile(BaseCommitTrailerKey + `:\s*([a-f0-9]{40})`)
	condensationTrailerRegex = regexp.MustCompile(CondensationTrailerKey + `:\s*(.+)`)
	sessionTrailerRegex      = regexp.MustCompile(SessionTrailerKey + `:\s*(.+)`)
	checkpointTrailerRegex   = regexp.MustCompile(CheckpointTrailerKey + `:\s*(` + checkpointID.Pattern + `)(?:\s|$)`)
)

// ParseStrategy extracts strategy from commit message.
// Returns the strategy name and true if found, empty string and false otherwise.
func ParseStrategy(commitMessage string) (string, bool) {
	matches := strategyTrailerRegex.FindStringSubmatch(commitMessage)
	if len(matches) > 1 {
		return NormalizeStrategyName(strings.TrimSpace(matches[1])), true
	}
	return "", false
}

// ParseMetadata extracts metadata dir from commit message.
// Returns the metadata directory and true if found, empty string and false otherwise.
func ParseMetadata(commitMessage string) (string, bool) {
	matches := metadataTrailerRegex.FindStringSubmatch(commitMessage)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1]), true
	}
	return "", false
}

// ParseTaskMetadata extracts task metadata dir from commit message.
// Returns the task metadata directory and true if found, empty string and false otherwise.
func ParseTaskMetadata(commitMessage string) (string, bool) {
	matches := taskMetadataTrailerRegex.FindStringSubmatch(commitMessage)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1]), true
	}
	return "", false
}

// ParseBaseCommit extracts the base commit SHA from a commit message.
// Returns the full SHA and true if found, empty string and false otherwise.
func ParseBaseCommit(commitMessage string) (string, bool) {
	matches := baseCommitTrailerRegex.FindStringSubmatch(commitMessage)
	if len(matches) > 1 {
		return matches[1], true
	}
	return "", false
}

// ParseCondensation extracts the condensation ID from a commit message.
// Returns the condensation ID and true if found, empty string and false otherwise.
func ParseCondensation(commitMessage string) (string, bool) {
	matches := condensationTrailerRegex.FindStringSubmatch(commitMessage)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1]), true
	}
	return "", false
}

// ParseSession extracts the session ID from a commit message.
// Returns the session ID and true if found, empty string and false otherwise.
// Note: If multiple Entire-Session trailers exist, this returns only the first one.
// Use ParseAllSessions to get all session IDs.
func ParseSession(commitMessage string) (string, bool) {
	matches := sessionTrailerRegex.FindStringSubmatch(commitMessage)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1]), true
	}
	return "", false
}

// ParseCheckpoint extracts the checkpoint ID from a commit message.
// Returns the CheckpointID and true if found, empty ID and false otherwise.
func ParseCheckpoint(commitMessage string) (checkpointID.CheckpointID, bool) {
	matches := checkpointTrailerRegex.FindStringSubmatch(commitMessage)
	if len(matches) > 1 {
		idStr := strings.TrimSpace(matches[1])
		// Validate it's a proper checkpoint ID
		if cpID, err := checkpointID.NewCheckpointID(idStr); err == nil {
			return cpID, true
		}
	}
	return checkpointID.EmptyCheckpointID, false
}

// ParseAllSessions extracts all session IDs from a commit message.
// Returns a slice of session IDs (may be empty if none found).
// Duplicate session IDs are deduplicated while preserving order.
// This is useful for commits that may have multiple Entire-Session trailers.
func ParseAllSessions(commitMessage string) []string {
	matches := sessionTrailerRegex.FindAllStringSubmatch(commitMessage, -1)
	if len(matches) == 0 {
		return nil
	}

	seen := make(map[string]bool)
	sessionIDs := make([]string, 0, len(matches))
	for _, match := range matches {
		if len(match) > 1 {
			sessionID := strings.TrimSpace(match[1])
			if !seen[sessionID] {
				seen[sessionID] = true
				sessionIDs = append(sessionIDs, sessionID)
			}
		}
	}
	return sessionIDs
}

// NormalizeStrategyName maps legacy strategy names to current names.
// These are the strategy names used during initial development and are kept for backwards
// compatibility.
func NormalizeStrategyName(name string) string {
	switch name {
	case "dual":
		return "auto-commit"
	case "shadow":
		return "manual-commit"
	default:
		return name
	}
}

// FormatStrategy creates a commit message with just the strategy trailer.
func FormatStrategy(message, strategy string) string {
	return fmt.Sprintf("%s\n\n%s: %s\n", message, StrategyTrailerKey, strategy)
}

// FormatTaskMetadata creates a commit message with task metadata trailer.
func FormatTaskMetadata(message, taskMetadataDir string) string {
	return fmt.Sprintf("%s\n\n%s: %s\n", message, MetadataTaskTrailerKey, taskMetadataDir)
}

// FormatTaskMetadataWithStrategy creates a commit message with task metadata and strategy trailers.
func FormatTaskMetadataWithStrategy(message, taskMetadataDir, strategy string) string {
	return fmt.Sprintf("%s\n\n%s: %s\n%s: %s\n", message, MetadataTaskTrailerKey, taskMetadataDir, StrategyTrailerKey, strategy)
}

// FormatSourceRef creates a formatted source ref string for the trailer.
// Format: "<branch>@<commit-hash-prefix>" (hash truncated to 12 chars)
func FormatSourceRef(branch, commitHash string) string {
	shortHash := commitHash
	if len(shortHash) > 12 {
		shortHash = shortHash[:12]
	}
	return fmt.Sprintf("%s@%s", branch, shortHash)
}

// FormatMetadata creates a commit message with metadata trailer.
func FormatMetadata(message, metadataDir string) string {
	return fmt.Sprintf("%s\n\n%s: %s\n", message, MetadataTrailerKey, metadataDir)
}

// FormatMetadataWithStrategy creates a commit message with metadata and strategy trailers.
func FormatMetadataWithStrategy(message, metadataDir, strategy string) string {
	return fmt.Sprintf("%s\n\n%s: %s\n%s: %s\n", message, MetadataTrailerKey, metadataDir, StrategyTrailerKey, strategy)
}

// FormatShadowCommit creates a commit message for manual-commit strategy checkpoints.
// Includes Entire-Metadata, Entire-Session, and Entire-Strategy trailers.
func FormatShadowCommit(message, metadataDir, sessionID string) string {
	var sb strings.Builder
	sb.WriteString(message)
	sb.WriteString("\n\n")
	sb.WriteString(fmt.Sprintf("%s: %s\n", MetadataTrailerKey, metadataDir))
	sb.WriteString(fmt.Sprintf("%s: %s\n", SessionTrailerKey, sessionID))
	sb.WriteString(fmt.Sprintf("%s: %s\n", StrategyTrailerKey, "manual-commit"))
	return sb.String()
}

// FormatShadowTaskCommit creates a commit message for manual-commit task checkpoints.
// Includes Entire-Metadata-Task, Entire-Session, and Entire-Strategy trailers.
func FormatShadowTaskCommit(message, taskMetadataDir, sessionID string) string {
	var sb strings.Builder
	sb.WriteString(message)
	sb.WriteString("\n\n")
	sb.WriteString(fmt.Sprintf("%s: %s\n", MetadataTaskTrailerKey, taskMetadataDir))
	sb.WriteString(fmt.Sprintf("%s: %s\n", SessionTrailerKey, sessionID))
	sb.WriteString(fmt.Sprintf("%s: %s\n", StrategyTrailerKey, "manual-commit"))
	return sb.String()
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/checkpoint"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"
	"entire.io/cli/cmd/entire/cli/strategy"
	"entire.io/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
	"github.com/spf13/cobra"
	"golang.org/x/term"
)

// commitInfo holds information about a commit for display purposes.
type commitInfo struct {
	SHA       string
	ShortSHA  string
	Message   string
	Author    string
	Email     string
	Date      time.Time
	Files     []string
	HasEntire bool
	SessionID string
}

// interaction holds a single prompt and its responses for display.
type interaction struct {
	Prompt    string
	Responses []string // Multiple responses can occur between tool calls
	Files     []string
}

// checkpointDetail holds detailed information about a checkpoint for display.
type checkpointDetail struct {
	Index            int
	ShortID          string
	Timestamp        time.Time
	IsTaskCheckpoint bool
	Message          string
	// Interactions contains all prompt/response pairs in this checkpoint.
	// Most strategies have one, but shadow condensations may have multiple.
	Interactions []interaction
	// Files is the aggregate list of all files modified (for backwards compat)
	Files []string
}

func newExplainCmd() *cobra.Command {
	var sessionFlag string
	var commitFlag string
	var checkpointFlag string
	var noPagerFlag bool
	var verboseFlag bool
	var fullFlag bool

	cmd := &cobra.Command{
		Use:   "explain",
		Short: "Explain a session, commit, or checkpoint",
		Long: `Explain provides human-readable context about sessions, commits, and checkpoints.

Use this command to understand what happened during agent-driven development,
either for self-review or to understand a teammate's work.

By default, explains the current session. Use flags to explain a specific
session, commit, or checkpoint.

Output verbosity levels (for --checkpoint):
  Default:   Summary view (ID, session, timestamp, tokens, intent)
  --verbose: + prompts and files touched
  --full:    + complete transcript

Only one of --session, --commit, or --checkpoint can be specified at a time.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			// Check if Entire is disabled
			if checkDisabledGuard(cmd.OutOrStdout()) {
				return nil
			}

			return runExplain(cmd.OutOrStdout(), sessionFlag, commitFlag, checkpointFlag, noPagerFlag, verboseFlag, fullFlag)
		},
	}

	cmd.Flags().StringVar(&sessionFlag, "session", "", "Explain a specific session (ID or prefix)")
	cmd.Flags().StringVar(&commitFlag, "commit", "", "Explain a specific commit (SHA or ref)")
	cmd.Flags().StringVarP(&checkpointFlag, "checkpoint", "c", "", "Explain a specific checkpoint (ID or prefix)")
	cmd.Flags().BoolVar(&noPagerFlag, "no-pager", false, "Disable pager output")
	cmd.Flags().BoolVarP(&verboseFlag, "verbose", "v", false, "Show prompts, files, and session IDs")
	cmd.Flags().BoolVar(&fullFlag, "full", false, "Show complete transcript")

	return cmd
}

// runExplain routes to the appropriate explain function based on flags.
func runExplain(w io.Writer, sessionID, commitRef, checkpointID string, noPager, verbose, full bool) error {
	// Count mutually exclusive flags
	flagCount := 0
	if sessionID != "" {
		flagCount++
	}
	if commitRef != "" {
		flagCount++
	}
	if checkpointID != "" {
		flagCount++
	}
	if flagCount > 1 {
		return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
	}

	// Route to appropriate handler
	if sessionID != "" {
		return runExplainSession(w, sessionID, noPager)
	}
	if commitRef != "" {
		return runExplainCommit(w, commitRef)
	}
	if checkpointID != "" {
		return runExplainCheckpoint(w, checkpointID, noPager, verbose, full)
	}

	// Default: explain current session
	return runExplainDefault(w, noPager)
}

// runExplainCheckpoint explains a specific checkpoint.
// Supports both committed checkpoints (by checkpoint ID) and temporary checkpoints (by ~sha prefix).
func runExplainCheckpoint(w io.Writer, checkpointIDPrefix string, noPager, verbose, full bool) error {
	repo, err := openRepository()
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}

	store := checkpoint.NewGitStore(repo)

	// Check if this is a temporary checkpoint (starts with ~)
	if strings.HasPrefix(checkpointIDPrefix, "~") {
		shaPrefix := strings.TrimPrefix(checkpointIDPrefix, "~")
		output, found := explainTemporaryCheckpoint(repo, store, shaPrefix, verbose, full)
		if !found {
			return fmt.Errorf("temporary checkpoint not found: %s", checkpointIDPrefix)
		}
		outputExplainContent(w, output, noPager)
		return nil
	}

	// Find in committed checkpoints by checkpoint ID prefix
	committed, err := store.ListCommitted(context.Background())
	if err != nil {
		return fmt.Errorf("failed to list checkpoints: %w", err)
	}

	var fullCheckpointID id.CheckpointID
	for _, info := range committed {
		if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
			fullCheckpointID = info.CheckpointID
			break
		}
	}

	if fullCheckpointID.IsEmpty() {
		return fmt.Errorf("checkpoint not found: %s", checkpointIDPrefix)
	}

	// Load checkpoint data
	result, err := store.ReadCommitted(context.Background(), fullCheckpointID)
	if err != nil {
		return fmt.Errorf("failed to read checkpoint: %w", err)
	}

	// Look up the commit message for this checkpoint
	commitMessage := findCommitMessageForCheckpoint(repo, fullCheckpointID)

	// Format and output
	output := formatCheckpointOutput(result, fullCheckpointID, commitMessage, verbose, full)
	outputExplainContent(w, output, noPager)
	return nil
}

// explainTemporaryCheckpoint finds and formats a temporary checkpoint by shadow commit hash prefix.
// Returns the formatted output and whether the checkpoint was found.
func explainTemporaryCheckpoint(repo *git.Repository, store *checkpoint.GitStore, shaPrefix string, verbose, full bool) (string, bool) {
	// Get current HEAD to find shadow branch
	head, err := repo.Head()
	if err != nil {
		return "", false
	}
	headShort := head.Hash().String()[:7]

	// List temporary checkpoints on current shadow branch
	tempCheckpoints, err := store.ListTemporaryCheckpoints(context.Background(), headShort, "", branchCheckpointsLimit)
	if err != nil {
		return "", false
	}

	// Find checkpoint matching the SHA prefix
	for _, tc := range tempCheckpoints {
		if strings.HasPrefix(tc.CommitHash.String(), shaPrefix) {
			// Found it - read metadata from shadow branch commit tree
			shadowCommit, commitErr := repo.CommitObject(tc.CommitHash)
			if commitErr != nil {
				return "", false
			}

			shadowTree, treeErr := shadowCommit.Tree()
			if treeErr != nil {
				return "", false
			}

			// Read prompts from shadow branch
			sessionPrompt := strategy.ReadSessionPromptFromTree(shadowTree, tc.MetadataDir)

			// Build output similar to formatCheckpointOutput but for temporary
			var sb strings.Builder
			shortID := tc.CommitHash.String()
			if len(shortID) > checkpointIDDisplayLength-1 {
				shortID = shortID[:checkpointIDDisplayLength-1]
			}
			fmt.Fprintf(&sb, "Checkpoint: ~%s [temporary]\n", shortID)
			fmt.Fprintf(&sb, "Session: %s\n", tc.SessionID)
			fmt.Fprintf(&sb, "Created: %s\n", tc.Timestamp.Format("2006-01-02 15:04:05"))
			sb.WriteString("\n")

			// Intent from prompt
			intent := "(not available)"
			if sessionPrompt != "" {
				lines := strings.Split(sessionPrompt, "\n")
				if len(lines) > 0 && lines[0] != "" {
					intent = truncateString(lines[0], maxIntentDisplayLength)
				}
			}
			fmt.Fprintf(&sb, "Intent: %s\n", intent)
			sb.WriteString("Outcome: (not generated)\n")

			// Verbose: show prompts
			if verbose || full {
				sb.WriteString("\n")
				sb.WriteString("Prompts:\n")
				if sessionPrompt != "" {
					sb.WriteString(sessionPrompt)
					sb.WriteString("\n")
				} else {
					sb.WriteString("  (none)\n")
				}
			}

			// Full: show transcript
			if full {
				// Try to read transcript from shadow branch
				transcriptPath := tc.MetadataDir + "/full.jsonl"
				if transcriptFile, fileErr := shadowTree.File(transcriptPath); fileErr == nil {
					if content, readErr := transcriptFile.Contents(); readErr == nil {
						sb.WriteString("\n")
						sb.WriteString("Transcript:\n")
						sb.WriteString(content)
						sb.WriteString("\n")
					}
				}
			}

			return sb.String(), true
		}
	}

	return "", false
}

// findCommitMessageForCheckpoint searches git history for a commit with the
// Entire-Checkpoint trailer matching the given checkpoint ID, and returns
// the first line of the commit message. Returns empty string if not found.
func findCommitMessageForCheckpoint(repo *git.Repository, checkpointID id.CheckpointID) string {
	// Get HEAD reference
	head, err := repo.Head()
	if err != nil {
		return ""
	}

	// Iterate through commit history (limit to recent commits for performance)
	commitIter, err := repo.Log(&git.LogOptions{
		From: head.Hash(),
	})
	if err != nil {
		return ""
	}
	defer commitIter.Close()

	count := 0

	for {
		commit, iterErr := commitIter.Next()
		if iterErr != nil {
			break
		}
		count++
		if count > maxCommitsToSearch {
			break
		}

		// Check if this commit has our checkpoint ID
		foundID, hasTrailer := trailers.ParseCheckpoint(commit.Message)
		if hasTrailer && foundID == checkpointID {
			// Return first line of commit message (without trailing newline)
			firstLine := strings.Split(commit.Message, "\n")[0]
			return strings.TrimSpace(firstLine)
		}
	}

	return ""
}

// formatCheckpointOutput formats checkpoint data based on verbosity level.
// Default: Summary (ID, session, timestamp, tokens, intent)
// Verbose: + prompts, files, commit message
// Full: + complete transcript
func formatCheckpointOutput(result *checkpoint.ReadCommittedResult, checkpointID id.CheckpointID, commitMessage string, verbose, full bool) string {
	var sb strings.Builder
	meta := result.Metadata

	// Header - always shown
	shortID := checkpointID
	if len(shortID) > checkpointIDDisplayLength {
		shortID = shortID[:checkpointIDDisplayLength]
	}
	fmt.Fprintf(&sb, "Checkpoint: %s\n", shortID)
	fmt.Fprintf(&sb, "Session: %s\n", meta.SessionID)
	fmt.Fprintf(&sb, "Created: %s\n", meta.CreatedAt.Format("2006-01-02 15:04:05"))

	// Token usage
	if meta.TokenUsage != nil {
		totalTokens := meta.TokenUsage.InputTokens + meta.TokenUsage.CacheCreationTokens +
			meta.TokenUsage.CacheReadTokens + meta.TokenUsage.OutputTokens
		fmt.Fprintf(&sb, "Tokens: %d\n", totalTokens)
	}

	sb.WriteString("\n")

	// Intent (use first line of prompts as fallback until AI summary is available)
	intent := "(not generated)"
	if result.Prompts != "" {
		lines := strings.Split(result.Prompts, "\n")
		if len(lines) > 0 && lines[0] != "" {
			intent = truncateString(lines[0], maxIntentDisplayLength)
		}
	}
	fmt.Fprintf(&sb, "Intent: %s\n", intent)
	sb.WriteString("Outcome: (not generated)\n")

	// Verbose: add commit message, files, and prompts
	if verbose || full {
		// Commit message section (only if available)
		if commitMessage != "" {
			sb.WriteString("\n")
			fmt.Fprintf(&sb, "Commit: %s\n", commitMessage)
		}

		sb.WriteString("\n")

		// Files section
		if len(meta.FilesTouched) > 0 {
			fmt.Fprintf(&sb, "Files: (%d)\n", len(meta.FilesTouched))
			for _, file := range meta.FilesTouched {
				fmt.Fprintf(&sb, "  - %s\n", file)
			}
		} else {
			sb.WriteString("Files: (none)\n")
		}

		sb.WriteString("\n")

		// Prompts section
		sb.WriteString("Prompts:\n")
		if result.Prompts != "" {
			sb.WriteString(result.Prompts)
			sb.WriteString("\n")
		} else {
			sb.WriteString("  (none)\n")
		}
	}

	// Full: add transcript
	if full {
		sb.WriteString("\n")
		sb.WriteString("Transcript:\n")
		if len(result.Transcript) > 0 {
			sb.Write(result.Transcript)
			sb.WriteString("\n")
		} else {
			sb.WriteString("  (none)\n")
		}
	}

	return sb.String()
}

// runExplainDefault shows all checkpoints on the current branch.
// This is the default view when no flags are provided.
func runExplainDefault(w io.Writer, noPager bool) error {
	return runExplainBranchDefault(w, noPager)
}

// branchCheckpointsLimit is the max checkpoints to show in branch view
const branchCheckpointsLimit = 100

// commitScanLimit is how far back to scan git history for checkpoints
const commitScanLimit = 500

// consecutiveMainLimit stops scanning after this many consecutive commits on main
// (indicates we've likely exhausted feature branch commits)
const consecutiveMainLimit = 100

// errStopIteration is used to stop commit iteration early
var errStopIteration = errors.New("stop iteration")

// getBranchCheckpoints returns checkpoints relevant to the current branch.
// This is strategy-agnostic - it queries checkpoints directly from the checkpoint store.
//
// Behavior:
//   - On feature branches: only show checkpoints unique to this branch (not in main)
//   - On default branch (main/master): show all checkpoints in history (up to limit)
//   - Includes both committed checkpoints (entire/sessions) and temporary checkpoints (shadow branches)
func getBranchCheckpoints(repo *git.Repository, limit int) ([]strategy.RewindPoint, error) {
	store := checkpoint.NewGitStore(repo)

	// Get all committed checkpoints for lookup
	committedInfos, err := store.ListCommitted(context.Background())
	if err != nil {
		committedInfos = nil // Continue without committed checkpoints
	}

	// Build map of checkpoint ID -> committed info
	committedByID := make(map[id.CheckpointID]checkpoint.CommittedInfo)
	for _, info := range committedInfos {
		if !info.CheckpointID.IsEmpty() {
			committedByID[info.CheckpointID] = info
		}
	}

	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	// Check if we're on the default branch
	isOnDefault, _, _ := IsOnDefaultBranch() //nolint:errcheck // Best-effort, defaults to false
	var mainBranchHash plumbing.Hash
	if !isOnDefault {
		mainBranchHash = strategy.GetMainBranchHash(repo)
	}

	// Walk git history and collect checkpoints
	iter, err := repo.Log(&git.LogOptions{
		From:  head.Hash(),
		Order: git.LogOrderCommitterTime,
	})
	if err != nil {
		return nil, fmt.Errorf("failed to get commit log: %w", err)
	}

	var points []strategy.RewindPoint
	count := 0
	consecutiveMainCount := 0

	err = iter.ForEach(func(c *object.Commit) error {
		if count >= commitScanLimit {
			return errStopIteration
		}
		count++

		// On feature branches, skip commits that are reachable from main
		// (but continue scanning - there may be more feature branch commits)
		if mainBranchHash != plumbing.ZeroHash {
			if isAncestorOf(repo, c.Hash, mainBranchHash) {
				consecutiveMainCount++
				if consecutiveMainCount >= consecutiveMainLimit {
					return errStopIteration // Likely exhausted feature branch commits
				}
				return nil // Skip this commit, continue scanning
			}
			consecutiveMainCount = 0 // Reset on feature branch commit
		}

		// Extract checkpoint ID from Entire-Checkpoint trailer
		cpID, found := trailers.ParseCheckpoint(c.Message)
		if !found {
			return nil // No checkpoint trailer, continue
		}

		// Look up checkpoint info
		cpInfo, found := committedByID[cpID]
		if !found {
			return nil // Checkpoint not in store, continue
		}

		// Create rewind point from committed info
		message := strings.Split(c.Message, "\n")[0]
		point := strategy.RewindPoint{
			ID:           c.Hash.String(),
			Message:      message,
			Date:         c.Author.When,
			IsLogsOnly:   true, // Committed checkpoints are logs-only
			CheckpointID: cpID,
			SessionID:    cpInfo.SessionID,
		}

		// Read session prompt from metadata branch (best-effort)
		if metadataTree, treeErr := strategy.GetMetadataBranchTree(repo); treeErr == nil && metadataTree != nil {
			point.SessionPrompt = strategy.ReadSessionPromptFromTree(metadataTree, cpID.Path())
		}

		points = append(points, point)
		return nil
	})

	if err != nil && !errors.Is(err, errStopIteration) {
		return nil, fmt.Errorf("error iterating commits: %w", err)
	}

	// Also get temporary checkpoints from shadow branch for current HEAD
	headShort := head.Hash().String()[:7]
	tempCheckpoints, _ := store.ListTemporaryCheckpoints(context.Background(), headShort, "", limit) //nolint:errcheck // Best-effort, continue without temp checkpoints
	for _, tc := range tempCheckpoints {
		shadowCommit, commitErr := repo.CommitObject(tc.CommitHash)
		if commitErr != nil {
			continue
		}

		// Filter out checkpoints with no code changes (only .entire/ metadata changed)
		// This also filters out the first checkpoint which is just a baseline copy
		if !hasCodeChanges(shadowCommit) {
			continue
		}

		// Read session prompt from the shadow branch commit's tree (not from entire/sessions)
		// Temporary checkpoints store their metadata in the shadow branch, not in entire/sessions
		var sessionPrompt string
		shadowTree, treeErr := shadowCommit.Tree()
		if treeErr == nil {
			sessionPrompt = strategy.ReadSessionPromptFromTree(shadowTree, tc.MetadataDir)
		}

		points = append(points, strategy.RewindPoint{
			ID:               tc.CommitHash.String(),
			Message:          tc.Message,
			MetadataDir:      tc.MetadataDir,
			Date:             tc.Timestamp,
			IsTaskCheckpoint: tc.IsTaskCheckpoint,
			ToolUseID:        tc.ToolUseID,
			SessionID:        tc.SessionID,
			SessionPrompt:    sessionPrompt,
			IsLogsOnly:       false, // Temporary checkpoints can be fully rewound
		})
	}

	// Sort by date, most recent first
	sort.Slice(points, func(i, j int) bool {
		return points[i].Date.After(points[j].Date)
	})

	// Apply limit
	if len(points) > limit {
		points = points[:limit]
	}

	return points, nil
}

// isAncestorOf checks if commit is an ancestor of (or equal to) target.
// Returns true if target can reach commit by following parent links.
func isAncestorOf(repo *git.Repository, commit, target plumbing.Hash) bool {
	if commit == target {
		return true
	}

	iter, err := repo.Log(&git.LogOptions{From: target})
	if err != nil {
		return false
	}

	found := false
	count := 0
	_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
		count++
		if count > 1000 {
			return errStopIteration
		}
		if c.Hash == commit {
			found = true
			return errStopIteration
		}
		return nil
	})

	return found
}

// runExplainBranchDefault shows all checkpoints on the current branch grouped by date.
// This is strategy-agnostic - it queries checkpoints directly.
func runExplainBranchDefault(w io.Writer, noPager bool) error {
	repo, err := openRepository()
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}

	// Get current branch name
	branchName := strategy.GetCurrentBranchName(repo)
	if branchName == "" {
		// Detached HEAD state - use short commit hash instead
		head, headErr := repo.Head()
		if headErr != nil {
			return fmt.Errorf("failed to get HEAD: %w", headErr)
		}
		branchName = "HEAD (" + head.Hash().String()[:7] + ")"
	}

	// Get checkpoints for this branch (strategy-agnostic)
	points, err := getBranchCheckpoints(repo, branchCheckpointsLimit)
	if err != nil {
		// Log error but continue with empty list
		points = nil
	}

	// Format output
	output := formatBranchCheckpoints(branchName, points)

	outputExplainContent(w, output, noPager)
	return nil
}

// outputExplainContent outputs content with optional pager support.
func outputExplainContent(w io.Writer, content string, noPager bool) {
	if noPager {
		fmt.Fprint(w, content)
	} else {
		outputWithPager(w, content)
	}
}

// runExplainSession explains a specific session.
func runExplainSession(w io.Writer, sessionID string, noPager bool) error {
	strat := GetStrategy()

	// Get session details
	session, err := strategy.GetSession(sessionID)
	if err != nil {
		if errors.Is(err, strategy.ErrNoSession) {
			return fmt.Errorf("session not found: %s", sessionID)
		}
		return fmt.Errorf("failed to get session: %w", err)
	}

	// Get source ref (metadata branch + commit) for this session
	sourceRef := strat.GetSessionMetadataRef(session.ID)

	// Gather checkpoint details
	checkpointDetails := gatherCheckpointDetails(strat, session)

	// For strategies like shadow where active sessions may not have checkpoints,
	// try to get the current session transcript directly
	if len(checkpointDetails) == 0 && len(session.Checkpoints) == 0 {
		checkpointDetails = gatherCurrentSessionDetails(strat, session)
	}

	// Format output
	output := formatSessionInfo(session, sourceRef, checkpointDetails)

	// Output with pager if appropriate
	if noPager {
		fmt.Fprint(w, output)
	} else {
		outputWithPager(w, output)
	}

	return nil
}

// gatherCurrentSessionDetails attempts to get transcript info for sessions without checkpoints.
// This handles strategies like shadow where active sessions may not have checkpoint commits.
func gatherCurrentSessionDetails(strat strategy.Strategy, session *strategy.Session) []checkpointDetail {
	// Try to get transcript via GetSessionContext which reads from metadata branch
	// For shadow, we can read the transcript from the same location pattern
	contextContent := strat.GetSessionContext(session.ID)
	if contextContent == "" {
		return nil
	}

	// Parse the context.md to extract the last prompt/summary
	// Context.md typically has sections like "# Prompt\n...\n## Summary\n..."
	detail := checkpointDetail{
		Index:     1,
		Timestamp: session.StartTime,
		Message:   "Current session",
	}

	// Try to extract prompt and summary from context.md
	lines := strings.Split(contextContent, "\n")
	var inPrompt, inSummary bool
	var promptLines, summaryLines []string

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "# ") && strings.Contains(strings.ToLower(trimmed), "prompt") {
			inPrompt = true
			inSummary = false
			continue
		}
		if strings.HasPrefix(trimmed, "## ") && strings.Contains(strings.ToLower(trimmed), "summary") {
			inPrompt = false
			inSummary = true
			continue
		}
		if strings.HasPrefix(trimmed, "## ") || strings.HasPrefix(trimmed, "# ") {
			inPrompt = false
			inSummary = false
			continue
		}

		if inPrompt {
			promptLines = append(promptLines, line)
		} else if inSummary {
			summaryLines = append(summaryLines, line)
		}
	}

	var inter interaction
	if len(promptLines) > 0 {
		inter.Prompt = strings.TrimSpace(strings.Join(promptLines, "\n"))
	}
	if len(summaryLines) > 0 {
		inter.Responses = []string{strings.TrimSpace(strings.Join(summaryLines, "\n"))}
	}

	// If we couldn't parse structured content, show the raw context
	if inter.Prompt == "" && len(inter.Responses) == 0 {
		inter.Responses = []string{contextContent}
	}

	if inter.Prompt != "" || len(inter.Responses) > 0 {
		detail.Interactions = []interaction{inter}
	}

	return []checkpointDetail{detail}
}

// gatherCheckpointDetails extracts detailed information for each checkpoint.
// Checkpoints come in newest-first order, but we number them oldest=1, newest=N.
func gatherCheckpointDetails(strat strategy.Strategy, session *strategy.Session) []checkpointDetail {
	details := make([]checkpointDetail, 0, len(session.Checkpoints))
	total := len(session.Checkpoints)

	for i, cp := range session.Checkpoints {
		detail := checkpointDetail{
			Index:            total - i, // Reverse numbering: oldest=1, newest=N
			Timestamp:        cp.Timestamp,
			IsTaskCheckpoint: cp.IsTaskCheckpoint,
			Message:          cp.Message,
		}

		// Use checkpoint ID for display (truncate long IDs)
		detail.ShortID = cp.CheckpointID.String()
		if len(detail.ShortID) > 12 {
			detail.ShortID = detail.ShortID[:12]
		}

		// Try to get transcript for this checkpoint
		transcriptContent, err := strat.GetCheckpointLog(cp)
		if err == nil {
			transcript, parseErr := parseTranscriptFromBytes(transcriptContent)
			if parseErr == nil {
				// Extract all prompt/response pairs from the transcript
				pairs := ExtractAllPromptResponses(transcript)
				for _, pair := range pairs {
					detail.Interactions = append(detail.Interactions, interaction(pair))
				}

				// Aggregate all files for the checkpoint
				fileSet := make(map[string]bool)
				for _, pair := range pairs {
					for _, f := range pair.Files {
						if !fileSet[f] {
							fileSet[f] = true
							detail.Files = append(detail.Files, f)
						}
					}
				}
			}
		}

		details = append(details, detail)
	}

	return details
}

// runExplainCommit explains a specific commit.
func runExplainCommit(w io.Writer, commitRef string) error {
	repo, err := openRepository()
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}

	// Resolve the commit reference
	hash, err := repo.ResolveRevision(plumbing.Revision(commitRef))
	if err != nil {
		return fmt.Errorf("commit not found: %s", commitRef)
	}

	commit, err := repo.CommitObject(*hash)
	if err != nil {
		return fmt.Errorf("failed to get commit: %w", err)
	}

	// Get files changed in this commit (diff from parent to current)
	var files []string
	commitTree, err := commit.Tree()
	if err == nil && commit.NumParents() > 0 {
		parent, parentErr := commit.Parent(0)
		if parentErr == nil {
			parentTree, treeErr := parent.Tree()
			if treeErr == nil {
				// Diff from parent to current commit to show what changed
				changes, diffErr := parentTree.Diff(commitTree)
				if diffErr == nil {
					for _, change := range changes {
						name := change.To.Name
						if name == "" {
							name = change.From.Name
						}
						files = append(files, name)
					}
				}
			}
		}
	}

	// Check for Entire metadata
	metadataDir, hasMetadata := trailers.ParseMetadata(commit.Message)
	sessionID, hasSession := trailers.ParseSession(commit.Message)

	// If no session trailer, try to extract from metadata path.
	// Note: extractSessionIDFromMetadata is defined in rewind.go as it's used
	// by both the rewind and explain commands for parsing metadata paths.
	if !hasSession && hasMetadata {
		sessionID = extractSessionIDFromMetadata(metadataDir)
		hasSession = sessionID != ""
	}

	// Build commit info
	fullSHA := hash.String()
	shortSHA := fullSHA
	if len(fullSHA) >= 7 {
		shortSHA = fullSHA[:7]
	}

	info := &commitInfo{
		SHA:       fullSHA,
		ShortSHA:  shortSHA,
		Message:   strings.Split(commit.Message, "\n")[0], // First line only
		Author:    commit.Author.Name,
		Email:     commit.Author.Email,
		Date:      commit.Author.When,
		Files:     files,
		HasEntire: hasMetadata || hasSession,
		SessionID: sessionID,
	}

	// Format and output
	output := formatCommitInfo(info)
	fmt.Fprint(w, output)

	return nil
}

// formatSessionInfo formats session information for display.
func formatSessionInfo(session *strategy.Session, sourceRef string, checkpoints []checkpointDetail) string {
	var sb strings.Builder

	// Session header
	fmt.Fprintf(&sb, "Session: %s\n", session.ID)
	fmt.Fprintf(&sb, "Strategy: %s\n", session.Strategy)

	if !session.StartTime.IsZero() {
		fmt.Fprintf(&sb, "Started: %s\n", session.StartTime.Format("2006-01-02 15:04:05"))
	}

	if sourceRef != "" {
		fmt.Fprintf(&sb, "Source Ref: %s\n", sourceRef)
	}

	fmt.Fprintf(&sb, "Checkpoints: %d\n", len(checkpoints))

	// Checkpoint details
	for _, cp := range checkpoints {
		sb.WriteString("\n")

		// Checkpoint header
		taskMarker := ""
		if cp.IsTaskCheckpoint {
			taskMarker = " [Task]"
		}
		fmt.Fprintf(&sb, "─── Checkpoint %d [%s] %s%s ───\n",
			cp.Index, cp.ShortID, cp.Timestamp.Format("2006-01-02 15:04"), taskMarker)
		sb.WriteString("\n")

		// Display all interactions in this checkpoint
		for i, inter := range cp.Interactions {
			// For multiple interactions, add a sub-header
			if len(cp.Interactions) > 1 {
				fmt.Fprintf(&sb, "### Interaction %d\n\n", i+1)
			}

			// Prompt section
			if inter.Prompt != "" {
				sb.WriteString("## Prompt\n\n")
				sb.WriteString(inter.Prompt)
				sb.WriteString("\n\n")
			}

			// Response section
			if len(inter.Responses) > 0 {
				sb.WriteString("## Responses\n\n")
				sb.WriteString(strings.Join(inter.Responses, "\n\n"))
				sb.WriteString("\n\n")
			}

			// Files modified for this interaction
			if len(inter.Files) > 0 {
				fmt.Fprintf(&sb, "Files Modified (%d):\n", len(inter.Files))
				for _, file := range inter.Files {
					fmt.Fprintf(&sb, "  - %s\n", file)
				}
				sb.WriteString("\n")
			}
		}

		// If no interactions, show message and/or files
		if len(cp.Interactions) == 0 {
			// Show commit message as summary when no transcript available
			if cp.Message != "" {
				sb.WriteString(cp.Message)
				sb.WriteString("\n\n")
			}
			// Show aggregate files if available
			if len(cp.Files) > 0 {
				fmt.Fprintf(&sb, "Files Modified (%d):\n", len(cp.Files))
				for _, file := range cp.Files {
					fmt.Fprintf(&sb, "  - %s\n", file)
				}
			}
		}
	}

	return sb.String()
}

// formatCommitInfo formats commit information for display.
func formatCommitInfo(info *commitInfo) string {
	var sb strings.Builder

	fmt.Fprintf(&sb, "Commit: %s (%s)\n", info.SHA, info.ShortSHA)
	fmt.Fprintf(&sb, "Date: %s\n", info.Date.Format("2006-01-02 15:04:05"))

	if info.HasEntire && info.SessionID != "" {
		fmt.Fprintf(&sb, "Session: %s\n", info.SessionID)
	}

	sb.WriteString("\n")

	// Message
	sb.WriteString("Message:\n")
	fmt.Fprintf(&sb, "  %s\n", info.Message)
	sb.WriteString("\n")

	// Files modified
	if len(info.Files) > 0 {
		fmt.Fprintf(&sb, "Files Modified (%d):\n", len(info.Files))
		for _, file := range info.Files {
			fmt.Fprintf(&sb, "  - %s\n", file)
		}
		sb.WriteString("\n")
	}

	// Note for non-Entire commits
	if !info.HasEntire {
		sb.WriteString("Note: No Entire session data available for this commit.\n")
	}

	return sb.String()
}

// outputWithPager outputs content through a pager if stdout is a terminal and content is long.
func outputWithPager(w io.Writer, content string) {
	// Check if we're writing to stdout and it's a terminal
	if f, ok := w.(*os.File); ok && f == os.Stdout && term.IsTerminal(int(f.Fd())) {
		// Get terminal height
		_, height, err := term.GetSize(int(f.Fd()))
		if err != nil {
			height = 24 // Default fallback
		}

		// Count lines in content
		lineCount := strings.Count(content, "\n")

		// Use pager if content exceeds terminal height
		if lineCount > height-2 {
			pager := os.Getenv("PAGER")
			if pager == "" {
				pager = "less"
			}

			cmd := exec.CommandContext(context.Background(), pager) //nolint:gosec // pager from env is expected
			cmd.Stdin = strings.NewReader(content)
			cmd.Stdout = f
			cmd.Stderr = os.Stderr

			if err := cmd.Run(); err != nil {
				// Fallback to direct output if pager fails
				fmt.Fprint(w, content)
			}
			return
		}
	}

	// Direct output for non-terminal or short content
	fmt.Fprint(w, content)
}

// Constants for formatting output
const (
	// maxCommitsToSearch is the maximum number of commits to search for checkpoint trailers
	maxCommitsToSearch = 500
	// maxIntentDisplayLength is the maximum length for intent text before truncation
	maxIntentDisplayLength = 80
	// maxMessageDisplayLength is the maximum length for checkpoint messages before truncation
	maxMessageDisplayLength = 80
	// maxPromptDisplayLength is the maximum length for session prompts before truncation
	maxPromptDisplayLength = 60
	// checkpointIDDisplayLength is the number of characters to show from checkpoint IDs
	checkpointIDDisplayLength = 12
)

// formatBranchCheckpoints formats checkpoint information for a branch.
// Groups commits by checkpoint ID and shows the prompt for each checkpoint.
func formatBranchCheckpoints(branchName string, points []strategy.RewindPoint) string {
	var sb strings.Builder

	// Branch header
	fmt.Fprintf(&sb, "Branch: %s\n", branchName)

	if len(points) == 0 {
		sb.WriteString("Checkpoints: 0\n")
		sb.WriteString("\nNo checkpoints found on this branch.\n")
		sb.WriteString("Checkpoints will appear here after you save changes during a Claude session.\n")
		return sb.String()
	}

	// Group by checkpoint ID
	groups := groupByCheckpointID(points)

	fmt.Fprintf(&sb, "Checkpoints: %d\n", len(groups))
	sb.WriteString("\n")

	// Output each checkpoint group
	for _, group := range groups {
		formatCheckpointGroup(&sb, group)
		sb.WriteString("\n")
	}

	return sb.String()
}

// checkpointGroup represents a group of commits sharing the same checkpoint ID.
type checkpointGroup struct {
	checkpointID string
	prompt       string
	isTemporary  bool // true if any commit is not logs-only (can be rewound)
	isTask       bool // true if this is a task checkpoint
	commits      []commitEntry
}

// commitEntry represents a single git commit within a checkpoint.
type commitEntry struct {
	date    time.Time
	gitSHA  string // short git SHA
	message string
}

// groupByCheckpointID groups rewind points by their checkpoint ID.
// Returns groups sorted by latest commit timestamp (most recent first).
func groupByCheckpointID(points []strategy.RewindPoint) []checkpointGroup {
	if len(points) == 0 {
		return nil
	}

	// Build map of checkpoint ID -> group
	groupMap := make(map[string]*checkpointGroup)
	var order []string // Track insertion order for stable iteration

	for _, point := range points {
		// Determine the checkpoint ID to use
		cpID := point.CheckpointID.String()
		if cpID == "" {
			// Temporary checkpoints use git commit hash with ~ prefix
			// Use 11 chars so total length with ~ is still 12
			cpID = point.ID
			if len(cpID) > checkpointIDDisplayLength-1 {
				cpID = cpID[:checkpointIDDisplayLength-1]
			}
			cpID = "~" + cpID
		}

		group, exists := groupMap[cpID]
		if !exists {
			group = &checkpointGroup{
				checkpointID: cpID,
				prompt:       point.SessionPrompt,
				isTemporary:  !point.IsLogsOnly,
				isTask:       point.IsTaskCheckpoint,
			}
			groupMap[cpID] = group
			order = append(order, cpID)
		}

		// Short git SHA (7 chars)
		gitSHA := point.ID
		if len(gitSHA) > 7 {
			gitSHA = gitSHA[:7]
		}

		group.commits = append(group.commits, commitEntry{
			date:    point.Date,
			gitSHA:  gitSHA,
			message: point.Message,
		})

		// Update flags - if any commit is temporary, the group is temporary
		if !point.IsLogsOnly {
			group.isTemporary = true
		}
	}

	// Sort commits within each group by date (most recent first)
	for _, group := range groupMap {
		sort.Slice(group.commits, func(i, j int) bool {
			return group.commits[i].date.After(group.commits[j].date)
		})
	}

	// Build result slice in order, then sort by latest commit
	result := make([]checkpointGroup, 0, len(order))
	for _, cpID := range order {
		result = append(result, *groupMap[cpID])
	}

	// Sort groups by latest commit timestamp (most recent first)
	sort.Slice(result, func(i, j int) bool {
		// Each group's commits are already sorted, so first commit is latest
		if len(result[i].commits) == 0 {
			return false
		}
		if len(result[j].commits) == 0 {
			return true
		}
		return result[i].commits[0].date.After(result[j].commits[0].date)
	})

	return result
}

// formatCheckpointGroup formats a single checkpoint group for display.
func formatCheckpointGroup(sb *strings.Builder, group checkpointGroup) {
	// Checkpoint ID (truncated for display)
	cpID := group.checkpointID
	if len(cpID) > checkpointIDDisplayLength {
		cpID = cpID[:checkpointIDDisplayLength]
	}

	// Build status indicators
	var indicators []string
	if group.isTask {
		indicators = append(indicators, "[task]")
	}
	if group.isTemporary {
		indicators = append(indicators, "[temporary]")
	}

	indicatorStr := ""
	if len(indicators) > 0 {
		indicatorStr = " " + strings.Join(indicators, " ")
	}

	// Prompt (truncated)
	var promptStr string
	if group.prompt == "" {
		promptStr = "(no prompt)"
	} else {
		// Quote actual prompts
		promptStr = fmt.Sprintf("%q", truncateString(group.prompt, maxPromptDisplayLength))
	}

	// Checkpoint header: [checkpoint_id] [indicators] prompt
	fmt.Fprintf(sb, "[%s]%s %s\n", cpID, indicatorStr, promptStr)

	// List commits under this checkpoint
	for _, commit := range group.commits {
		// Format: "  MM-DD HH:MM (git_sha) message"
		dateTimeStr := commit.date.Format("01-02 15:04")
		message := truncateString(commit.message, maxMessageDisplayLength)
		fmt.Fprintf(sb, "  %s (%s) %s\n", dateTimeStr, commit.gitSHA, message)
	}
}

// hasCodeChanges returns true if the commit has changes to non-metadata files.
// Used by getBranchCheckpoints to filter out metadata-only temporary checkpoints.
// Returns false only if the commit has a parent AND only modified .entire/ metadata files.
//
// First commits (no parent) are always considered to have code changes since they
// capture the working copy state at session start - real uncommitted work.
//
// This filters out periodic transcript saves that don't change code.
func hasCodeChanges(commit *object.Commit) bool {
	// First commit on shadow branch captures working copy state - always meaningful
	if commit.NumParents() == 0 {
		return true
	}

	parent, err := commit.Parent(0)
	if err != nil {
		return true // Can't check, assume meaningful
	}

	commitTree, err := commit.Tree()
	if err != nil {
		return true
	}

	parentTree, err := parent.Tree()
	if err != nil {
		return true
	}

	changes, err := parentTree.Diff(commitTree)
	if err != nil {
		return true
	}

	// Check if any non-metadata file was changed
	for _, change := range changes {
		name := change.To.Name
		if name == "" {
			name = change.From.Name
		}
		// Skip .entire/ metadata files
		if !strings.HasPrefix(name, ".entire/") {
			return true
		}
	}

	return false
}

// truncateString truncates a string to the specified length, adding "..." if truncated.
func truncateString(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	if maxLen <= 3 {
		return s[:maxLen]
	}
	return s[:maxLen-3] + "..."
}

